import { readFileSync } from 'node:fs';
import { captureCrmScreenshot } from './fixtures/crm-screenshots';
import { expect, expectNoHorizontalOverflow, installAppShellMocks, test } from './fixtures/app';

// Generated by the isolated PostgreSQL AS014 regression, not a second filter
// implementation. Browser routes replay its actual service responses locally.
const fixturePath = process.env.AS014_BROWSER_FIXTURE;
test.skip(!fixturePath, 'Run CRM workspace PostgreSQL tests with AS014_BROWSER_FIXTURE=/tmp/... first.');
test.use({ timezoneId: 'Asia/Kolkata' });

type Fixture = {
  collections: Record<string, Record<string, unknown>>;
  reminders: Array<{ contactId: number }>;
  work: unknown; contact: unknown; summary: unknown;
};

test('AS014 legacy open reminders agree across directory filters, work, reminders and detail', async ({ page, audit }) => {
  const fixture = JSON.parse(readFileSync(fixturePath!, 'utf8')) as Fixture;
  const mutations: string[] = [];
  const collectionQueries: URLSearchParams[] = [];
  page.on('request', request => {
    if (new URL(request.url()).pathname.startsWith('/api/') && !['GET', 'HEAD'].includes(request.method())) mutations.push(request.method());
  });
  await page.route('**/api/**', route => route.fulfill({ json: {} }));
  await installAppShellMocks(page);
  await page.route('**/api/crm/analytics', route => route.fulfill({ json: { success: true, data: { totalContacts: 3, winRate: 0, pipelineValueByCurrency: {} } } }));
  await page.route('**/api/crm/assignees', route => route.fulfill({ json: { success: true, data: [{ id: 29, name: 'Fixture member' }] } }));
  await page.route('**/api/crm/contacts?*', route => {
    const query = new URL(route.request().url()).searchParams;
    collectionQueries.push(query);
    const key = `${query.get('followup') || 'all'}:${query.get('search') || ''}${query.get('priority') === 'high' ? ':high' : ''}`;
    const response = fixture.collections[key];
    expect(response, `Database fixture response for ${key}`).toBeDefined();
    return route.fulfill({ json: { success: true, ...response } });
  });
  await page.route('**/api/crm/work?*', route => route.fulfill({ json: { success: true, data: fixture.work } }));
  await page.route('**/api/crm/reminders**', route => {
    const contactId = new URL(route.request().url()).searchParams.get('contactId');
    return route.fulfill({ json: { success: true, data: contactId ? fixture.reminders.filter(reminder => reminder.contactId === Number(contactId)) : fixture.reminders } });
  });
  await page.route('**/api/crm/contacts/1**', route => {
    const path = new URL(route.request().url()).pathname;
    if (path.endsWith('/workspace-summary')) return route.fulfill({ json: { success: true, data: fixture.summary } });
    if (path.endsWith('/conversations')) return route.fulfill({ json: { success: true, conversations: [], sentMessages: [], pagination: { page: 1, total: 0, totalPages: 0 } } });
    return route.fulfill({ json: { success: true, data: fixture.contact } });
  });
  await page.route('**/api/proposals/related?*', route => route.fulfill({ json: [] }));

  await page.goto('/dashboard/crm/contacts');
  await expect(page.getByRole('status').filter({ hasText: '3 matching contacts' })).toBeVisible();
  await page.getByRole('button', { name: 'Advanced filters', exact: true }).click();
  await page.getByLabel('Follow-up', { exact: true }).selectOption('overdue');
  await expect(page.getByRole('status').filter({ hasText: '2 matching contacts' })).toBeVisible();
  await expect(page.getByRole('link', { name: 'Ada', exact: true })).toHaveCount(1);
  await expect(page.getByRole('link', { name: 'Ben', exact: true })).toHaveCount(1);
  await expectNoHorizontalOverflow(page);
  await page.getByLabel('Search contacts', { exact: true }).fill('Ada');
  await expect(page.getByRole('status').filter({ hasText: '1 matching contacts' })).toBeVisible();
  await page.getByLabel('Follow-up', { exact: true }).selectOption('none');
  await expect(page.getByRole('status').filter({ hasText: '0 matching contacts' })).toBeVisible();
  await expect(page.getByRole('link', { name: 'Ada', exact: true })).toHaveCount(0);
  // Only the empty result is captured; no contact rows or destinations appear.
  await captureCrmScreenshot(page, `${process.env.CRM_QA_SCREENSHOT_DIR || 'test-results'}/AS014-empty-${test.info().project.name}.png`);
  await page.getByLabel('Search contacts', { exact: true }).fill('');
  await expect(page.getByRole('link', { name: 'Virtual', exact: true })).toBeVisible();
  await page.getByLabel('Follow-up', { exact: true }).selectOption('upcoming');
  await expect(page.getByRole('status').filter({ hasText: '0 matching contacts' })).toBeVisible();
  await page.getByRole('button', { name: 'Clear filters', exact: true }).first().click();
  await expect(page.getByRole('status').filter({ hasText: '3 matching contacts' })).toBeVisible();
  await page.getByLabel('Follow-up', { exact: true }).selectOption('overdue');
  await page.getByLabel('Search contacts', { exact: true }).fill('Ada');
  await expect(page.getByRole('status').filter({ hasText: '1 matching contacts' })).toBeVisible();
  await page.getByLabel('Priority', { exact: true }).selectOption('high');
  await page.getByLabel('Assigned to', { exact: true }).selectOption('29');
  await page.getByLabel('Filter by pipeline stage', { exact: true }).selectOption('new');
  await expect.poll(() => collectionQueries.some(query => query.get('followup') === 'overdue' && query.get('search') === 'Ada' && query.get('priority') === 'high' && query.get('ownerUserId') === '29' && query.get('pipelineStatus') === 'new')).toBe(true);
  await expect(page.getByRole('status').filter({ hasText: '1 matching contacts' })).toBeVisible();

  await page.goto('/dashboard/crm/work?type=reminder');
  await expect(page.getByRole('button', { name: 'Follow-ups 3', exact: true })).toBeVisible();
  await expect(page.locator('article').getByText('Overdue', { exact: true })).toHaveCount(3);
  await expectNoHorizontalOverflow(page);
  await page.goto('/dashboard/crm/reminders');
  await page.getByRole('button', { name: 'overdue (3)', exact: true }).click();
  await expect(page.getByText('Notification sent', { exact: true })).toBeVisible();
  await expect(page.getByText('Notification delivery failed.', { exact: false })).toBeVisible();
  await expectNoHorizontalOverflow(page);
  await page.goto('/dashboard/crm/contacts/1');
  await expect(page.getByRole('heading', { name: 'Ada', exact: true })).toBeVisible();
  if (test.info().project.name === 'mobile-chromium') await page.getByRole('button', { name: 'Contact details', exact: true }).click();
  const followups = page.getByRole('region', { name: 'Contact follow-ups', exact: true });
  await expect(followups.getByRole('heading', { name: 'Follow-ups (2)', exact: true })).toBeVisible();
  await expect(followups.getByText('Notification sent', { exact: true })).toBeVisible();
  await expect(followups.getByText('Overdue', { exact: true })).toHaveCount(2);
  await expectNoHorizontalOverflow(page);
  expect(mutations).toEqual([]);
  expect(audit.blockedMutations).toEqual([]); expect(audit.consoleErrors).toEqual([]);
});
